'use strict';
const $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',ledger:'M5 3h14v18H5z M8 7h8 M8 11h8 M8 15h5',run:'M8 5l11 7-11 7z',report:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h6',check:'M5 12l4 4L19 6',fix:'M4 5h16v15H4z M8 3v4 M16 3v4 M8 13l3 3 5-6',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',back:'M19 12H5 M10 7l-5 5 5 5',info:'M12 16v-4 M12 8h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',alert:'M12 3L2 21h20z M12 9v5 M12 17h.01',logout:'M9 4H4v16h5 M9 12h12 M17 8l4 4-4 4',refresh:'M20 6v5h-5 M4 18v-5h5 M5 8a8 8 0 0 1 13-3l2 3 M4 16l2 3a8 8 0 0 0 13-3',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5'};
const icon=(name='grid')=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const statusNames={ACTIVE:'进行中',ARCHIVED:'已归档',QUEUED:'排队中',RUNNING:'执行中',WAITING_REVIEW:'待审核',REVIEW_REJECTED:'已退回',FAILED:'运行失败',CANCELLED:'已取消',COMPLETED:'已发布',DRAFT:'草稿',IN_REVIEW:'审核中',APPROVED:'待发布',PUBLISHED:'已发布',CHANGES_REQUESTED:'待修改',TODO:'待处理',IN_PROGRESS:'处理中',PENDING_ACCEPTANCE:'待验收',REWORK:'退回整改',ACCEPTED:'已验收',DONE:'已完成',VOID:'已作废',PENDING:'待决策',REJECTED:'已退回'};
const colors={ACTIVE:'green',COMPLETED:'green',PUBLISHED:'green',ACCEPTED:'green',DONE:'green',RUNNING:'blue',IN_PROGRESS:'blue',IN_REVIEW:'blue',WAITING_REVIEW:'orange',PENDING_ACCEPTANCE:'purple',REWORK:'red',FAILED:'red',REVIEW_REJECTED:'red',CHANGES_REQUESTED:'red',APPROVED:'blue'};
const tag=(v,label)=>`<span class="tag ${colors[v]||''}">${esc(label||statusNames[v]||v)}</span>`;
const fmt=x=>x?String(x).replace('T',' ').slice(0,16):'—';
const key=()=>crypto.randomUUID();
const dayAdd=(date,n)=>new Date(Date.parse(date+'T00:00:00Z')+n*86400000).toISOString().slice(0,10);
const pageModules={};
const S={me:null,project:null,pid:localStorage.getItem('eaw-project')||'p_demo',route:'overview',detail:null,confirmation:null,import:null,dirty:false,ledgerPage:0};
let poll=null,toastTimer=null,renderSequence=0;
async function api(path,data){const response=await fetch('/api'+path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-EAW-Request':'1'},body:data===undefined?undefined:JSON.stringify(data)});let body=await response.json();if(!response.ok){const error=new Error(body.message+(body.trace_id?'\n排障编号：'+body.trace_id:''));error.code=body.error;error.status=response.status;throw error;}return body;}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3600);}
function failure(error,root=document){const el=root.querySelector('.inline-error');if(el){el.textContent=error.message;el.className='inline-error error';}else toast(error.message);}
function brand(){return '<div class="brand"><div class="brandmark">E</div><div><strong>Enterprise AI Work</strong><small>企业智能协同</small></div></div>';}
function login(){S.me=null;S.project=null;$('#app').innerHTML=`<div class="login"><section class="loginbrand">${brand()}<h1>让项目事实，<br>走向处理结果。</h1><p>可信的进度汇总，明确的人工决策，<br>连续的整改与验收。让协作形成闭环。</p><div class="loginsteps"><span>01 / 核对项目事实</span><span>02 / 审核报告建议</span><span>03 / 推动整改验收</span></div></section><section class="loginform"><form data-form="login"><h2>登录工作空间</h2><p class="muted sub">使用项目账号，继续推进你的工作。</p><div class="field"><label for="username">账号</label><input id="username" name="username" autocomplete="username" required placeholder="输入账号"></div><div class="field"><label for="password">密码</label><input id="password" name="password" type="password" autocomplete="current-password" required placeholder="输入密码"></div><div class="inline-error"></div><button class="primary" type="submit">登录 ${icon('arrow')}</button><div class="demoaccounts"><strong>本地演示空间</strong><br>项目经理 <code>manager</code> · 负责人 <code>owner</code> · 审核人 <code>reviewer</code><br>演示密码：<code>EawDemo!2026</code><br>内置台账用于流程验证；分析为演示规则，文档检索与摘录在本地运行，未调用真实 LLM。</div></form></section></div>`;}
const roleName=role=>({manager:'项目经理',member:'项目成员',reviewer:'报告审核人',knowledge_admin:'知识管理员',service_runner:'计划执行身份',enterprise_admin:'企业管理员'}[role]||'项目成员');
const currentProjectRole=()=>S.project?.project?.role||S.me?.projects.find(p=>p.id===S.pid)?.role;
const manager=()=>currentProjectRole()==='manager';
const canDraft=()=>['manager','reviewer'].includes(currentProjectRole());
const person=id=>S.project?.members.find(x=>x.id===id)?.name||id||'未指定';
const NAV_GROUPS=[
  {id:'work',label:'日常协作',icon:'grid',routes:[['overview','grid','项目空间'],['questions','info','引用问答'],['reports','report','报告审核'],['fixes','fix','整改协同'],['notifications','clock','待办与通知'],['artifacts','report','成果中心']]},
  {id:'project',label:'项目与资料',icon:'ledger',routes:[['ledger','ledger','业务台账'],['knowledge','ledger','知识中心'],['planning','ledger','快照与里程碑'],['portfolio','grid','跨项目概览'],['members','grid','项目与成员'],['feedback','info','知识反馈'],['downloads','download','导出与下载'],['retention','ledger','资料保留']]},
  {id:'automation',label:'分析与自动化',icon:'run',routes:[['analyses','info','开放风险分析'],['templates','run','应用模板'],['runs','run','任务运行'],['schedules','clock','定时汇总'],['flows','run','流程编排']]},
  {id:'management',label:'管理与运营',icon:'clock',routes:[['configs','grid','模板与 Agent'],['connections','ledger','数据连接'],['tools','ledger','工具连接'],['operations','grid','运行评估'],['evaluations','check','版本评测'],['reminders','clock','提醒与订阅'],['admin','grid','管理控制台'],['audit','ledger','审计记录']]}
];
const NAV_STATES=new Map();
function navigationRoute(){
  const route=(location.hash.replace(/^#\//,'')||S.route||'overview').split('/')[0];
  return ({new:'runs','flow-runs':'flows',libraries:'knowledge',retrieval:'knowledge',fragments:'knowledge'})[route]||route;
}
function navigationScope(){return 'eaw-navigation:'+S.me.user.id+':'+S.pid;}
function navigationState(){
  const scope=navigationScope();
  if(!NAV_STATES.has(scope)){
    const state={open:{work:true,project:false,automation:false,management:false},scrollTop:0,route:null};
    try{
      const saved=JSON.parse(localStorage.getItem(scope)||'{}');
      for(const group of NAV_GROUPS)if(typeof saved[group.id]==='boolean')state.open[group.id]=saved[group.id];
      const top=Number(sessionStorage.getItem(scope+':scroll')||0);if(Number.isFinite(top))state.scrollTop=Math.max(0,top);
    }catch{}
    NAV_STATES.set(scope,state);
  }
  return NAV_STATES.get(scope);
}
function visibleNavigationGroups(){
  return NAV_GROUPS.map(group=>({...group,routes:group.routes.filter(([id])=>(canDraft()||id!=='runs')&&(!pageModules[id]?.visible||pageModules[id].visible()))})).filter(group=>group.routes.length);
}
function persistNavigation(scope,state){
  try{localStorage.setItem(scope,JSON.stringify(state.open));sessionStorage.setItem(scope+':scroll',String(state.scrollTop));}catch{}
}
function openActiveNavigationGroup(state,groups){
  const active=navigationRoute();
  if(state.route!==active){
    const group=groups.find(group=>group.routes.some(([id])=>id===active));
    if(group)state.open[group.id]=true;
    state.route=active;
  }
}
function navigation(){
  const state=navigationState(),groups=visibleNavigationGroups(),active=navigationRoute();
  openActiveNavigationGroup(state,groups);
  const current=S.me.projects.find(project=>project.id===S.pid);
  return `<aside class="sidebar" data-nav-scope="${esc(navigationScope())}">${brand()}
    <div class="workspace">${S.me.projects.length?`<label for="project-switch">当前项目</label><select id="project-switch" aria-label="切换项目" title="${esc(current?.name||'切换项目')}">${S.me.projects.map(p=>`<option value="${p.id}" ${p.id===S.pid?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`:'项目协同工作区'}</div>
    <div class="navlabel">工作区</div><nav class="nav" aria-label="主导航">${groups.map(group=>`<section class="nav-group" data-nav-group="${group.id}"><button type="button" class="nav-group-toggle" data-nav-toggle="${group.id}" aria-expanded="${state.open[group.id]}" aria-controls="nav-items-${group.id}" title="${group.label}"><span class="nav-group-icon">${icon(group.icon)}</span><span class="nav-group-label">${group.label}</span><svg class="nav-chevron" viewBox="0 0 16 16" aria-hidden="true"><path d="m6 4 4 4-4 4"/></svg></button><div class="nav-group-items" id="nav-items-${group.id}" ${state.open[group.id]?'':'hidden'}>${group.routes.map(([id,ic,label])=>`<a href="#/${id}" data-nav-route="${id}" title="${label}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></a>`).join('')}</div></section>`).join('')}</nav>
    <div class="navbottom"><div class="localnote"><span class="dot"></span>本地演示空间 · 开发版</div><div class="profile"><div class="avatar">${esc(S.me.user.name.slice(-2))}</div><div class="info">${esc(S.me.user.name)}<small>${roleName(S.me.projects.find(p=>p.id===S.pid)?.role||((S.me.system_roles||[]).includes('enterprise_admin')?'enterprise_admin':'member'))}</small></div><button data-action="logout" aria-label="退出登录" title="退出登录">${icon('logout')}</button></div></div></aside>`;
}
function navigationSignature(){
  return JSON.stringify([S.me.user,S.pid,S.me.system_roles,S.me.projects.map(p=>[p.id,p.name,p.role]),currentProjectRole(),visibleNavigationGroups().map(group=>[group.id,group.routes.map(([id])=>id)])]);
}
function bindNavigation(){
  const sidebar=$('#app > .sidebar'),nav=sidebar.querySelector('.nav'),scope=sidebar.dataset.navScope,state=navigationState();
  sidebar.dataset.navSignature=navigationSignature();
  nav.scrollTop=state.scrollTop;
  nav.addEventListener('scroll',()=>{state.scrollTop=nav.scrollTop;try{sessionStorage.setItem(scope+':scroll',String(state.scrollTop));}catch{}},{passive:true});
}
function updateNavigation(){
  const sidebar=$('#app > .sidebar');if(!sidebar||!S.me)return;
  const state=navigationState(),groups=visibleNavigationGroups(),active=navigationRoute();
  openActiveNavigationGroup(state,groups);
  for(const group of sidebar.querySelectorAll('[data-nav-group]')){
    const id=group.dataset.navGroup,expanded=Boolean(state.open[id]);
    group.querySelector('[data-nav-toggle]').setAttribute('aria-expanded',String(expanded));
    group.querySelector('.nav-group-items').hidden=!expanded;
    group.classList.toggle('has-active',[...group.querySelectorAll('[data-nav-route]')].some(link=>link.dataset.navRoute===active));
  }
  for(const link of sidebar.querySelectorAll('[data-nav-route]')){
    const selected=link.dataset.navRoute===active;link.classList.toggle('active',selected);
    if(selected)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');
  }
  const reportLink=sidebar.querySelector('[data-nav-route="reports"]'),count=(S.project?.reports||[]).filter(r=>r.status==='IN_REVIEW').length;
  if(reportLink){
    let badge=reportLink.querySelector('.navcount');
    if(count){if(!badge){badge=document.createElement('b');badge.className='navcount';reportLink.append(badge);}badge.textContent=String(count);badge.setAttribute('aria-label',count+' 份报告待审');}
    else badge?.remove();
  }
  persistNavigation(navigationScope(),state);
}
function shell(content){
  const names={overview:'项目空间',ledger:'业务台账',runs:'任务运行',reports:'报告审核',fixes:'整改协同',new:'新建进度汇总',knowledge:'知识中心',questions:'引用问答'};
  const body=`<header class="topbar"><span>工作空间 <span style="margin:0 10px;color:#c5cdda">/</span> <b>${names[S.route]||pageModules[S.route]?.title||'项目空间'}</b></span><div class="topright"><span>上海时区 · ${esc(S.me.today)}</span><span class="mode">演示规则模式</span></div></header><main class="main">${content}</main>`;
  const root=$('#app'),sidebar=root.querySelector(':scope > .sidebar'),work=root.querySelector(':scope > .shell');
  if(!sidebar||!work){root.innerHTML=navigation()+'<div class="shell">'+body+'</div>';bindNavigation();}
  else{
    if(sidebar.dataset.navSignature!==navigationSignature()){
      const previous=NAV_STATES.get(sidebar.dataset.navScope);if(previous){previous.scrollTop=sidebar.querySelector('.nav').scrollTop;persistNavigation(sidebar.dataset.navScope,previous);}
      const template=document.createElement('template');template.innerHTML=navigation();sidebar.replaceWith(template.content.firstElementChild);bindNavigation();
    }
    work.innerHTML=body;
  }
  updateNavigation();
}
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-nav-toggle]');if(!button)return;
  const sidebar=button.closest('.sidebar'),state=navigationState(),id=button.dataset.navToggle;
  state.open[id]=!state.open[id];button.setAttribute('aria-expanded',String(state.open[id]));
  sidebar.querySelector('#'+button.getAttribute('aria-controls')).hidden=!state.open[id];
  state.scrollTop=sidebar.querySelector('.nav').scrollTop;persistNavigation(sidebar.dataset.navScope,state);
});
function pagehead(title,sub,actions='',eyebrow='PROJECT WORKSPACE'){return `<div class="pagehead"><div><h1>${esc(title)}</h1><div class="sub">${esc(sub)}</div></div><div class="actions">${actions}</div></div>`;}
function empty(title,description,action=''){return `<div class="empty">${icon('report')}<h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`;}
function stats(m){return `<div class="metrics"><div class="metric"><div class="label">任务总数</div><strong>${m.total}</strong><span class="unit">项</span><div class="detail">有效任务 · 不含已取消</div></div><div class="metric"><div class="label">已完成任务</div><strong>${m.completed}</strong><span class="unit">项</span><div class="detail">按台账完成状态计算</div></div><div class="metric alert"><div class="label">未完成逾期</div><strong>${m.overdue_count}</strong><span class="unit">项</span><div class="detail">当天到期不计为逾期</div></div><div class="metric"><div class="label">本期完成</div><strong>${m.period_completed}</strong><span class="unit">项</span><div class="detail">周期内有效完成记录</div></div></div>`;}
function newButton(){return manager()&&S.project.project.status==='ACTIVE'?`<button class="primary" data-action="new">${icon('plus')}新建进度汇总</button>`:'';}
function overview(){const p=S.project,m=p.metrics,counts={waiting:p.reports.filter(x=>x.status==='IN_REVIEW').length,published:p.reports.filter(x=>x.status==='PUBLISHED').length,fixes:p.rectifications.filter(x=>!['ACCEPTED','CANCELLED'].includes(x.state)).length};return `${pagehead('项目空间','掌握当前进度，让风险落实到下一步行动。',newButton())}<section class="panel"><div class="projectsummary"><div><div class="actions"><span class="tag">${esc(p.project.code)}</span>${tag(p.project.status)}</div><h2 class="projectname">${esc(p.project.name)}</h2><div class="projectmeta"><span>${p.members.length} 位项目成员</span><span>台账更新 ${fmt(p.updated_at)}</span><span>当前状态快照</span></div></div><div class="progresswrap"><div class="ring" style="--percent:${m.completion_rate||0}%"><span>${m.completion_rate??'—'}${m.completion_rate===null?'':'<small>%</small>'}</span></div></div></div>${stats(m)}</section><div class="notice">${icon('info')}<span>当前使用模拟台账与项目资料。完成率由规则计算，文档可检索与引用；分析未调用真实 LLM，原因仍需人工核实。${p.updated_at&&Date.now()-Date.parse(p.updated_at)>86400000?' 台账超过 24 小时未更新，请确认数据时效。':''}</span></div><div class="twocol"><section class="panel"><div class="panelhead"><h2>需要关注的事项 <span class="sub">/ ${m.overdue_count}</span></h2><a class="sub" href="#/ledger">查看台账 →</a></div>${m.overdue_tasks.length?m.overdue_tasks.map(r=>`<div class="listrow"><div class="riskicon">${icon('clock')}</div><div class="grow"><strong>${esc(r.title)}</strong><p>${esc(r.task_id)} <span style="margin:0 5px">·</span> ${esc(person(r.owner_id))} <span style="margin:0 5px">·</span> 截止 ${esc(r.due_date)}</p></div><span class="tag orange">逾期 ${r.overdue_days} 天</span></div>`).join(''):empty('当前没有未完成逾期','继续核对数据缺口与待处理事项。')}</section><section class="panel"><div class="panelhead"><h2>闭环推进</h2><span class="sub">当前项目</span></div><div class="panelbody"><div class="summaryline"><span class="number">01</span><div class="grow"><h3>人工审核</h3><p>${counts.waiting} 份报告等待核对</p></div><a href="#/reports">${icon('arrow')}</a></div><div class="summaryline"><span class="number">02</span><div class="grow"><h3>整改跟进</h3><p>${counts.fixes} 项整改尚未结束</p></div><a href="#/fixes">${icon('arrow')}</a></div><div class="summaryline"><span class="number">03</span><div class="grow"><h3>正式成果</h3><p>${counts.published} 份报告已发布归档</p></div><a href="#/reports">${icon('arrow')}</a></div></div></section></div><section class="panel"><div class="panelhead"><h2>最近报告</h2><a class="sub" href="#/reports">全部报告 →</a></div>${reportList(p.reports.slice(0,3))}</section>`;}
function reportList(rows){return rows.length?`<div class="tablewrap"><table><thead><tr><th>报告名称 / 运行标识</th><th>版本</th><th>状态</th><th>发起时间</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td class="title"><a href="#/reports/${r.id}">项目进度汇总</a><div class="mono sub">${esc(r.run_id)}</div></td><td>v${r.current_version}</td><td>${tag(r.status)}</td><td>${fmt(r.created_at)}</td><td><a href="#/reports/${r.id}">查看 →</a></td></tr>`).join('')}</tbody></table></div>`:empty('还没有进度报告','使用右上角的“新建进度汇总”，发起第一份报告。');}
function ledger(){return `${pagehead('业务台账','所有统计与风险事实的结构化来源。',manager()?`<button data-action="import">${icon('plus')}导入 CSV</button>`:'','PROJECT DATA')}<div class="filters"><input id="ledger-search" aria-label="搜索台账任务" placeholder="搜索任务编号或名称"><select id="ledger-status" aria-label="筛选任务状态"><option value="">全部状态</option><option value="TODO">待处理</option><option value="IN_PROGRESS">处理中</option><option value="DONE">已完成</option><option value="CANCELLED">已取消</option></select><span class="sub">${S.project.ledger.length} 项任务</span></div><section class="panel"><div id="ledger-table"></div></section><div class="notice">${icon('info')}<span>统计采用上海时区自然日。没有截止日的任务不判断逾期；缺少期末快照时，不能用当前数据还原历史。</span></div>`;}
function ledgerTable(){const q=($('#ledger-search')?.value||'').toLowerCase(),st=$('#ledger-status')?.value||'';const filtered=S.project.ledger.filter(r=>(r.title+r.task_id).toLowerCase().includes(q)&&(!st||r.status===st)),page=S.ledgerPage||0,rows=filtered.slice(page*20,page*20+20);$('#ledger-table').innerHTML=`<div class="tablewrap"><table><thead><tr><th>任务编号 / 名称</th><th>负责人</th><th>状态</th><th>计划截止</th><th>完成时间</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td class="title"><div class="mono sub">${esc(r.task_id)}</div>${esc(r.title)}</td><td>${esc(person(r.owner_id))}</td><td>${tag(r.status)}</td><td>${esc(r.due_date||'未提供')}${!['DONE','CANCELLED'].includes(r.status)&&r.due_date&&r.due_date<S.me.today?'<div class="sub" style="color:#bb8241">已逾期</div>':''}</td><td>${esc(r.completed_at?.slice(0,10)||'—')}</td><td>${manager()?`<button class="text" data-action="edit-ledger" data-id="${esc(r.task_id)}">编辑</button>`:''}</td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('没有匹配的任务','调整搜索词或状态筛选。'):''}<div class="pagination"><span>共 ${filtered.length} 项 · 第 ${page+1} 页</span><button class="small" data-action="ledger-prev" ${page===0?'disabled':''}>上一页</button><button class="small" data-action="ledger-next" ${(page+1)*20>=filtered.length?'disabled':''}>下一页</button></div>`;}
function runs(){return `${pagehead('任务运行','从不可变快照到正式成果，每一步都有记录。',newButton(),'WORKFLOW RUNS')}<section class="panel">${S.project.runs.length?`<div class="tablewrap"><table><thead><tr><th>运行标识</th><th>状态</th><th>当前阶段</th><th>创建时间</th><th></th></tr></thead><tbody>${S.project.runs.map(r=>`<tr><td class="mono">${esc(r.id)}</td><td>${tag(r.state,r.phase==='WAITING_REVISION'?'待修改':null)}</td><td>${esc(phaseName(r.phase))}</td><td>${fmt(r.created_at)}</td><td><a href="#/runs/${r.id}">运行详情 →</a></td></tr>`).join('')}</tbody></table></div>`:empty('还没有运行记录','发起汇总后，可在这里追踪所有执行步骤。',newButton())}</section>`;}
function phaseName(p){return {ANALYSIS:'分析与校验',HUMAN_REVIEW:'人工审核',WAITING_REVISION:'等待修订',PUBLISHING:'发布归档',PUBLISHED:'正式发布',CANCELLED:'已终止'}[p]||p;}
function runDetail(r){const nodeIds=r.data.mode==='HUMAN_REVISION'?['DeriveDraft','HumanReview','PublishReport']:['ValidateInput','ReadSnapshot','RuleCompute','RetrieveEvidence','AnalyzeAgent','ValidateOutput','SaveDraft','HumanReview','PublishReport'];const labels=r.data.mode==='HUMAN_REVISION'?['派生修订草稿','人工审核','发布归档']:['参数与权限校验','读取冻结快照','规则统计','绑定台账证据','风险建议（演示规则）','输出校验','保存原稿','人工审核','发布归档'];if(r.data.mode==='HUMAN_TAKEOVER'){nodeIds.splice(7,0,'ManualTakeover');labels.splice(7,0,'人工接管草稿');};return `<a class="back" href="#/runs">${icon('back')}所有运行</a>${pagehead('进度汇总运行',r.id,`<button data-action="refresh">${icon('refresh')}刷新</button>${r.report?`<button class="primary" data-action="open-report" data-id="${r.report.id}">查看报告 ${icon('arrow')}</button>`:''}`,'WORKFLOW RUN')}<div class="twocol"><section class="panel"><div class="panelhead"><h2>执行轨迹</h2>${tag(r.state,r.phase==='WAITING_REVISION'?'待修改':null)}</div><div class="panelbody timeline">${nodeIds.map((id,i)=>{const as=r.attempts.filter(a=>a.node===id),a=as.at(-1);return `<div class="timelineitem ${!a?'pending':a.status==='FAILED'?'failed':a.status==='WAITING'?'waiting':''}"><h3>${labels[i]}${a?` <span class="sub">/ 第 ${a.attempt} 次</span>`:''}</h3><p>${esc(a?.summary||'尚未执行')}</p>${a?`<div class="mono sub">${fmt(a.started_at)}</div>`:''}</div>`;}).join('')}</div></section><div><section class="panel"><div class="panelhead"><h2>运行信息</h2></div><div class="panelbody"><dl class="keyvalues"><dt>当前阶段</dt><dd>${esc(phaseName(r.phase))}</dd><dt>统计周期</dt><dd>${esc(r.data.period_start)}<br>至 ${esc(r.data.period_end)}</dd><dt>数据截点</dt><dd>${fmt(r.data.cutoff_time)}<br><span class="sub">截至采集时刻，非全天数据</span></dd>${r.data.data_source?`<dt>数据连接</dt><dd>${esc(r.data.data_source.name)} · 水位 ${r.data.data_source.watermark??r.data.data_source.kind??'历史快照'}</dd>`:''}${r.data.schedule_id?`<dt>定时来源</dt><dd><a href="#/schedules/${r.data.schedule_id}">查看执行计划 →</a></dd>`:''}<dt>输入快照</dt><dd class="mono">${esc(r.snapshot_id)}</dd><dt>执行版本</dt><dd>${esc(r.data.versions.workflow)}<br>${esc(r.data.versions.rules)}</dd><dt>活跃执行</dt><dd>${r.data.active_seconds??'历史未采集'} 秒<br><span class="sub">不含等待审核时间</span></dd><dt>累计尝试</dt><dd>${r.data.node_calls} / 40 次</dd><dt>工具调用</dt><dd>${r.data.tool_calls??'历史未采集'} 次</dd><dt>Agent 版本</dt><dd>${esc(r.data.versions.prompt)}</dd><dt>模型配置</dt><dd>${esc(r.data.versions.model)}</dd><dt>模型用量</dt><dd>${r.data.model_calls||0} 调用 · ${r.data.tokens||0} tokens<br><span class="sub">演示规则 · 未产生成本</span></dd></dl></div></section>${r.data.error?`<div class="error">${esc(r.data.error.message)}<div class="mono">${esc(r.data.error.code)}<br>${esc(r.data.error.trace_id)}</div></div>`:''}${manager()?`<div class="actions">${r.state==='FAILED'?`<button class="primary" data-action="resume-run">从检查点恢复</button>${r.phase!=='PUBLISHING'?'<button data-report-action="takeover">人工接管草稿</button>':''}`:''}${!['COMPLETED','CANCELLED'].includes(r.state)?'<button class="danger" data-action="cancel-run">取消运行</button>':''}</div>`:''}</div></div>`;}
function reviewers(selected){return S.project.members.filter(m=>['manager','reviewer'].includes(m.role)).map(m=>`<option value="${m.id}" ${m.id===selected?'selected':''}>${esc(m.name)} · ${roleName(m.role)}</option>`).join('');}
function newRun(){return `<a class="back" href="#/overview">${icon('back')}项目空间</a>${pagehead('新建进度汇总','冻结一份台账，让报告有据可查。','','NEW PROGRESS REPORT')}<div class="stepstrip"><span class="current"><b>1</b>核对数据与范围</span><i></i><span><b>2</b>生成与人工审核</span><i></i><span><b>3</b>确认整改与验收</span></div><div class="twocol"><section class="panel"><div class="panelhead"><h2>汇总参数</h2><span class="tag">固定工作流</span></div><div class="panelbody"><form data-form="new-run"><div class="field"><label>所属项目</label><input value="${esc(S.project.project.name)}" readonly></div><div class="field"><label>报告模板</label><select name="workflow_id" aria-label="报告模板">${(S.me.templates||[]).filter(t=>t.scene==='PROGRESS'&&(!t.allowed_projects?.length||t.allowed_projects.includes(S.pid))).map(t=>`<option value="${t.id}" ${G.selectedTemplate===t.id?'selected':''}>${esc(t.name)} · v${t.version}</option>`).join('')}</select></div><div class="field"><label for="run-source">台账来源</label><select id="run-source" name="connection_id"><option value="">内置项目台账</option>${(S.project.connections||[]).map(c=>`<option value="${c.id}" ${ADV.source===c.id?'selected':''}>${esc(c.name)} · ${fmt(c.last_success_at)}</option>`).join('')}</select><small class="sub">选择连接时使用其最近有效快照，截点以同步成功时间为准；右侧为内置台账参考。</small></div><div class="formgrid"><div class="field"><label for="period-start">统计开始日期</label><input id="period-start" name="period_start" type="date" value="${dayAdd(S.me.today,-6)}" max="${S.me.today}" required></div><div class="field"><label for="period-end">统计结束日期</label><input id="period-end" name="period_end" type="date" value="${S.me.today}" max="${S.me.today}" required></div></div><p class="sub">截至今天的报告以当前采集时刻为截点；历史周期须有期末快照。</p><div class="field"><label for="reviewer">指定审核人</label><select id="reviewer" name="reviewer_id">${reviewers(S.me.user.id)}</select></div><label class="check"><input name="include_documents" type="checkbox" checked><span>纳入当前可用的授权项目资料，并冻结本次引用版本。</span></label><label class="check"><input name="acknowledge_gaps" type="checkbox" required><span>我已检查右侧数据与缺口，确认以当前台账生成报告；原因分析待人工核实。</span></label><div class="inline-error"></div><div class="actions" style="margin-top:25px"><button class="primary" type="submit">${icon('run')}发起进度汇总</button><a href="#/overview">取消</a></div></form></div></section><div><section class="panel"><div class="panelhead"><h2>数据预检</h2><span class="tag blue">当前状态</span></div><div class="panelbody"><dl class="keyvalues"><dt>内置台账参考</dt><dd>${S.project.ledger.length} 项</dd><dt>最近更新</dt><dd>${fmt(S.project.updated_at)}</dd><dt>知识资料</dt><dd>${S.project.document_count||0} 份可用授权资料</dd><dt>数字来源</dt><dd>内置台账 + rules-v1</dd><dt>分析模式</dt><dd>演示规则（非 LLM）</dd></dl></div></section><div class="notice warning">${icon('alert')}<div><strong>需要确认的数据缺口</strong><ul class="gaps">${S.project.metrics.missing.filter(x=>!S.project.document_count||!x.includes('未接入会议纪要')).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div></div></div>`;}
function reports(){return `${pagehead('报告审核','核对数字与证据，再将建议变成正式成果。',newButton(),'REPORTS & REVIEW')}<section class="panel">${reportList(S.project.reports)}</section>`;}
function eventsHTML(events){const names={REPORT_REVISION_DERIVED:'从正式版派生修订',REPORT_SUPERSEDED:'由新版替代',REPORT_DRAFTED:'保存原稿',REVIEW_SUBMITTED:'提交审核',REVIEW_WITHDRAWN:'撤回审核',REPORT_REVISED:'保存人工修订',REPORT_APPROVED:'人工审核通过',REPORT_REJECTED:'报告退回',PUBLISH_REQUESTED:'请求发布',REPORT_PUBLISHED:'正式发布',ACTION_PREPARED:'准备整改确认单',REPORT_EXPORTED:'导出报告',RECTIFICATION_CREATED:'确认创建整改',RECTIFICATION_START:'开始处理',RECTIFICATION_UPDATE:'更新处理记录',RECTIFICATION_SUBMIT:'提交验收',RECTIFICATION_RETURN:'退回整改',RECTIFICATION_ACCEPT:'通过验收',RECTIFICATION_CANCEL:'取消整改',RECTIFICATION_REASSIGN:'调整负责人',RECTIFICATION_RESCHEDULE:'调整截止日期',RECTIFICATION_COMMUNICATION:'补录沟通摘要'};return events.length?[...events].reverse().map(e=>`<div class="activity"><strong>${esc(names[e.action]||e.action)}</strong><p>${esc(e.actor_name)} · ${fmt(e.created_at)}</p>${e.data.comment||e.data.reason?`<div class="narrative">${esc(e.data.comment||e.data.reason)}</div>`:''}${e.data.evidence?`<details><summary class="sub">查看本次处理证据</summary><div class="pre">${esc(e.data.evidence)}</div></details>`:''}</div>`).join(''):'<p class="sub">暂无活动记录</p>';}
function reportDetail(r){const d=r.current.data,activeApproval=r.approval?.state==='PENDING'&&r.status==='IN_REVIEW',canReview=activeApproval&&!r.approval.data?.needs_transfer&&r.approval.reviewer_id===S.me.user.id,runActive=!['CANCELLED','COMPLETED'].includes(r.run.state);return `<a class="back" href="#/reports">${icon('back')}全部报告</a>${pagehead('项目进度报告',`${d.period_start} — ${d.period_end} · ${S.project.project.code}`,`<button data-action="refresh">${icon('refresh')}刷新</button>${manager()?'<button data-report-action="regenerate">复制参数重新生成</button>':''}${r.status==='PUBLISHED'&&manager()?'<button data-report-action="derive-report">派生修订草稿</button>':''}<button data-report-action="compare-report">正文对比</button><button data-delivery-action="export" data-format="md">${icon('download')}导出 Markdown</button><button data-delivery-action="export" data-format="docx">导出 Word</button><button data-delivery-action="export" data-format="pdf">导出 PDF</button>${r.status==='PUBLISHED'&&manager()&&d.risks.length?'<button class="primary" data-action="prepare-fixes">'+icon('plus')+'确认整改事项</button>':''}`,'PROGRESS REPORT')}<div class="reportlayout"><section class="panel"><div class="panelhead"><div class="actions">${tag(r.status)}<span class="sub">当前版本 v${r.current_version}</span></div><a class="sub" href="#/runs/${r.run_id}">查看运行 →</a></div>${r.relations?.length?`<div class="versionnote">${r.relations.map(x=>x.child_report_id===r.id?`来源：<a href="#/reports/${x.parent_report_id}">${x.kind==='REVISION'?'正式版修订':'重新生成'} v${x.parent_version} →</a>`:`后续：<a href="#/reports/${x.child_report_id}">${x.kind==='REVISION'?'派生修订':'重新生成'} →</a>`).join(' · ')}</div>`:''}${r.approval?.data?.needs_transfer?`<div class="error">审核人授权已失效，当前审核暂停。${esc(r.approval.data.transfer_reason)}，请由项目经理转交审核。</div>`:''}${r.source_updates?.length?`<div class="versionnote">${r.source_updates.map(x=>`${esc(x.title)}已有 v${x.active_version}；当前引用保留 v${x.document_version}，未自动替换。`).join(' ')}</div>`:''}<div class="pilltabs" aria-label="报告版本">${r.versions.map(v=>`<button class="small ${v.version===r.current_version?'active':''}" data-action="view-version" data-version="${v.version}">${v.version===1?'原稿':'人工修订'} v${v.version}</button>`).join('')}</div><article class="reportbody" id="report-content">${reportArticle(d,r.current_version,r.current.reason)}</article><div class="reviewactions"><div class="sub" style="margin-bottom:13px">${r.approval?'指定审核人：'+esc(person(r.approval.reviewer_id))+' · 审核绑定 v'+r.approval.report_version+' / '+esc(r.approval.content_hash.slice(0,12)):'报告尚未提交审核'}<br>批准仅授权发布此正文；整改需另行确认。</div><div class="actions">${canReview?'<button class="primary" data-action="approve">核对通过并发布</button><button class="danger" data-action="reject">退回修改</button>':''}${manager()&&r.status==='IN_REVIEW'&&runActive?'<button data-action="withdraw">撤回并修订</button><button data-platform-action="transfer-review">转交审核</button>':''}${manager()&&['DRAFT','CHANGES_REQUESTED'].includes(r.status)&&runActive?'<button class="primary" data-action="edit-report">编辑修订</button><button data-action="submit-review">提交审核</button>':''}${r.status==='APPROVED'&&manager()&&r.run.state==='FAILED'?'<button class="primary" data-action="resume-publish">恢复发布</button>':''}${!canReview&&activeApproval?'<span class="sub">等待指定审核人处理</span>':''}${r.run.state==='CANCELLED'?'<span class="sub">运行已取消，旧审核单已作废。</span>':''}</div></div></section><aside><section class="panel"><div class="panelhead"><h2>数据与来源</h2><span class="tag">台账 / 文档</span></div><div class="panelbody"><div class="sub">数据截点 ${fmt(d.cutoff_time)}<br>${d.data_source?.kind?'来源声明为期末快照，具体来源见正文':'截至采集时间，非完整全天数据'}</div><p class="mono muted">${esc(d.snapshot_id)}</p>${[...d.evidence].sort((a,b)=>(b.kind==='DOCUMENT')-(a.kind==='DOCUMENT')).map(ev=>`<div class="evidence"><button class="text" data-action="evidence" data-id="${esc(ev.evidence_id)}">${esc(ev.evidence_id)} · ${esc(ev.title)}</button><p>${ev.kind==='DOCUMENT'?'文档定位':ev.kind==='MILESTONE'?'冻结里程碑计划':'冻结台账行'} ${esc(ev.locator)} · ${ev.kind==='DOCUMENT'?'':'v'}${esc(String(ev.version).slice(0,16))}</p></div>`).join('')}</div></section><section class="panel"><div class="panelhead"><h2>审核与活动</h2></div><div class="panelbody">${eventsHTML(r.events)}</div></section></aside></div>`;}
function reportArticleOld(d,version,reason){return `<div class="sub">正文 v${version} · ${esc(reason)}</div><div class="versionnote">${d.human_supplement?'人工补充需核实。':'演示规则原稿，分析未调用 LLM；文档来源按实际引用展示。'} 数字锁定于原始快照。</div><div class="metrics reportmetrics"><div class="metric"><div class="label">任务完成率</div><strong>${d.metrics.completion_rate??'—'}<span class="unit">%</span></strong></div><div class="metric"><div class="label">已完成 / 总任务</div><strong>${d.metrics.completed}<span class="unit"> / ${d.metrics.total}</span></strong></div><div class="metric alert"><div class="label">未完成逾期</div><strong>${d.metrics.overdue_count}<span class="unit"> 项</span></strong></div><div class="metric"><div class="label">本期完成</div><strong>${d.metrics.period_completed}<span class="unit"> 项</span></strong></div></div><details><summary class="sub">查看计算口径</summary><p>任务完成率 = 已完成任务 / 非取消任务。截止日早于截点本地日期且未完成为逾期；当天到期不算逾期。完成时间缺失不计入本期完成数。业务数字不由模型生成。</p></details><h3>风险事实与行动建议</h3>${d.risks.length?d.risks.map(risk=>`<section class="riskblock"><div class="actions"><h3 style="margin:0;flex:1">${esc(risk.title)}</h3><span class="tag">低 · 规则初值</span></div><p><strong>事实</strong> · ${esc(risk.fact)}</p><p><strong>原因</strong> · ${esc(risk.hypothesis)}</p><p><strong>建议</strong> · ${esc(risk.recommendation)}</p><div class="actions">${risk.evidence_ids.map(id=>`<button class="text" data-action="evidence" data-id="${esc(id)}">${esc(id)} ↗</button>`).join('')}<span class="sub">负责人、截止日与验收标准待确认</span></div></section>`).join(''):'<p>规则未识别未完成逾期项，仍需核对资料缺口。</p>'}<h3>主要进展与下周期关注</h3><div class="narrative">${esc(d.narrative)}</div><h3>数据缺口</h3><ul class="gaps">${d.missing.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;}

function fixes(){const filter=$('#fix-status')?.value||'';return `${pagehead('整改协同','每个确认的问题，都有负责人、证据与验收结果。','','RECTIFICATION LOOP')}<div class="filters"><select id="fix-status" aria-label="筛选整改状态"><option value="">全部状态</option>${['TODO','IN_PROGRESS','PENDING_ACCEPTANCE','REWORK','ACCEPTED','CANCELLED'].map(v=>`<option value="${v}">${statusNames[v]}</option>`).join('')}</select><span class="sub">共 ${S.project.rectifications.length} 项整改</span></div><section class="panel" id="fix-table">${fixTable('')}</section>`;}
function fixTable(filter){const fs=S.project.rectifications.filter(f=>!filter||f.state===filter);return fs.length?`<div class="tablewrap"><table><thead><tr><th>整改事项</th><th>负责人</th><th>截止日期</th><th>状态</th><th></th></tr></thead><tbody>${fs.map(f=>`<tr><td class="title"><a href="#/fixes/${f.id}">${esc(f.data.title)}</a><div class="sub mono">${esc(f.risk_id)} · 报告 v${f.report_version}</div></td><td>${esc(f.owner_name)}</td><td>${esc(f.data.due_date)}${f.data.due_date<S.me.today&&!['ACCEPTED','CANCELLED'].includes(f.state)?`<div class="sub" style="color:#b98440">${f.state==='PENDING_ACCEPTANCE'?'待验收超时':'处理逾期'}</div>`:''}</td><td>${tag(f.state)}</td><td><a href="#/fixes/${f.id}">跟进 →</a></td></tr>`).join('')}</tbody></table></div>`:empty('暂无整改事项','在已发布报告中选择风险，明确负责人和验收标准后创建。','<a href="#/reports">前往报告 →</a>');}
function fixDetailBase(f){const own=f.owner_id===S.me.user.id,end=['ACCEPTED','CANCELLED'].includes(f.state);return `<a class="back" href="#/fixes">${icon('back')}全部整改</a>${pagehead(f.data.title,f.id,`<button data-action="refresh">${icon('refresh')}刷新</button>`,'RECTIFICATION DETAIL')}${f.state==='ACCEPTED'?`<div class="notice success">${icon('check')}<span><strong>整改已验收完成</strong> · ${esc(f.events.find(e=>e.action==='RECTIFICATION_ACCEPT')?.actor_name||'项目经理')} · ${fmt(f.events.find(e=>e.action==='RECTIFICATION_ACCEPT')?.created_at)}<br>处理证据与验收结论已归档，可从活动记录核对全过程。</span></div>`:''}<div class="twocol"><div><section class="panel"><div class="panelhead"><h2>处理与验收</h2>${tag(f.state)}</div><div class="panelbody"><dl class="keyvalues"><dt>负责人</dt><dd>${esc(person(f.owner_id))}</dd><dt>截止日期</dt><dd>${esc(f.data.due_date)}</dd><dt>问题描述</dt><dd>${esc(f.data.description)}</dd><dt>验收标准</dt><dd>${esc(f.data.acceptance)}</dd><dt>来源报告</dt><dd><a href="#/reports/${f.report_id}">项目进度汇总 v${f.report_version} →</a></dd><dt>来源风险</dt><dd class="mono">${esc(f.risk_id)}</dd></dl>${f.data.last_submission?`<h3 style="margin-top:25px">最近一次处理证据</h3><div class="pre">${esc(f.data.last_submission.comment)}\n\n${esc(f.data.last_submission.evidence)}</div>`:''}</div><div class="reviewactions"><div class="actions">${own&&['TODO','REWORK'].includes(f.state)?'<button class="primary" data-action="fix-transition" data-command="START">开始处理</button>':''}${own&&['IN_PROGRESS','REWORK'].includes(f.state)?'<button class="primary" data-action="fix-transition" data-command="SUBMIT">提交验收</button><button data-action="fix-transition" data-command="UPDATE">更新处理记录</button>':''}${manager()&&f.state==='PENDING_ACCEPTANCE'&&!own?'<button class="primary" data-action="fix-transition" data-command="ACCEPT">通过验收</button><button class="danger" data-action="fix-transition" data-command="RETURN">退回整改</button>':''}${manager()&&!end?'<button data-action="fix-transition" data-command="REASSIGN">改派负责人</button><button data-action="fix-transition" data-command="RESCHEDULE">调整截止日</button><button class="danger" data-action="fix-transition" data-command="CANCEL">取消整改</button>':''}${own&&f.state==='PENDING_ACCEPTANCE'?'<span class="sub">已提交，等待另一位项目经理验收。</span>':''}${end?'<span class="sub">此任务已结束，处理与验收记录已归档。</span>':''}</div></div></section></div><section class="panel"><div class="panelhead"><h2>活动记录</h2><span class="sub">全程留痕</span></div><div class="panelbody">${eventsHTML(f.events)}</div></section></div>`;}
async function refresh(){clearTimeout(poll);const seq=++renderSequence;try{S.me=await api('/me');if(!S.me.projects.some(p=>p.id===S.pid))S.pid=S.me.projects[0]?.id;const preliminary=(location.hash.replace(/^#\//,'')||'overview').split('/');if(pageModules[preliminary[0]]?.global){S.route=preliminary[0];S.detail=await pageModules[S.route].load(preliminary[1]);if(seq!==renderSequence)return;shell(pageModules[S.route].render(S.detail,preliminary[1]));if(pageModules[S.route]?.isActive?.(S.detail))poll=setTimeout(()=>{if(!$('#dialog').open)refresh();},650);return;}if(!S.me.projects.some(p=>p.id===S.pid))S.pid=S.me.projects[0]?.id;if(!S.pid){S.project=null;$('#app').innerHTML='<main class="loading"><h1>尚无项目权限</h1><p>请由项目经理授予项目权限后刷新。</p><p><a href="#/admin">管理控制台</a></p><button data-action="refresh">刷新</button> <button data-action="logout">退出登录</button></main>';return;}const project=await api('/projects/'+S.pid);if(seq!==renderSequence)return;S.project=project;const route=(location.hash.replace(/^#\//,'')||'overview').split('/');S.route=route[0];S.detail=null;let content;if(pageModules[S.route]){const module=pageModules[S.route];S.detail=await module.load(route[1],route[2]);if(seq!==renderSequence)return;content=module.render(S.detail,route[1]);}else if(route[1]&&['runs','reports','fixes'].includes(S.route)){const endpoint={runs:'runs',reports:'reports',fixes:'rectifications'}[S.route];const detail=await api('/'+endpoint+'/'+route[1]);if(seq!==renderSequence)return;S.detail=detail;content={runs:runDetail,reports:reportDetail,fixes:fixDetail}[S.route](detail);}else content=({overview,ledger,runs,reports,fixes,new:newRun}[S.route]||overview)();shell(content);if(S.route==='ledger')ledgerTable();const active=S.route==='runs'&&S.detail&&['QUEUED','RUNNING'].includes(S.detail.state)||S.route==='reports'&&S.detail&&S.detail.status==='APPROVED'&&['QUEUED','RUNNING'].includes(S.detail.run.state);if(active||pageModules[S.route]?.isActive?.(S.detail))poll=setTimeout(()=>{if(!$('#dialog').open)refresh();},650);}catch(error){if(error.status===401){login();}else if(error.status===403){S.project=null;S.me=null;$('#app').innerHTML=`<main class="loading"><h1>没有此内容的访问权限</h1><p class="error">${esc(error.message)}</p><a href="#/overview">返回项目空间</a> <button data-action="logout">退出登录</button></main>`;}else if(S.me&&S.project){shell(`${pagehead('暂时无法打开','') }<div class="error">${esc(error.message)}</div><button data-action="refresh">刷新</button>`);}else{$('#app').innerHTML=`<div class="loading"><div class="error">${esc(error.message)}</div><button data-action="refresh">重试</button></div>`;}}}
function modal(title,content,footer='',form=''){const d=$('#dialog');d.innerHTML=`${form?`<form data-form="${form}">`:''}<div class="dialoghead"><h2 id="dialog-title">${esc(title)}</h2><button type="button" class="close" data-action="close" aria-label="关闭">×</button></div>${content}<div class="inline-error"></div>${footer?`<div class="footer">${footer}</div>`:''}${form?'</form>':''}`;d.showModal();}
function closeModal(){const d=$('#dialog');d.close();S.dirty=false;}
const cancelButton='<button type="button" data-action="close">取消</button>';
const submitButton=label=>`<button class="primary" type="submit">${esc(label)}</button>`;
function reasonModal(title,command,description=''){S.command=command;modal(title,`${description?`<p class="muted">${esc(description)}</p>`:''}<div class="field"><label for="reason">说明 / 原因</label><textarea id="reason" name="reason" required placeholder="填写便于追踪的处理说明"></textarea></div>`,cancelButton+submitButton(title),'reason');}
function prepareFixes(){const r=S.detail;S.fixReport=r;modal('选择要创建的整改',`<p class="sub">报告已发布。请逐项确认负责人、截止日与验收标准，然后核对最终清单。</p>${r.current.data.risks.map((risk,i)=>`<section class="confirmitem" data-risk="${esc(risk.risk_id)}"><label class="check"><input name="selected" type="checkbox" value="${esc(risk.risk_id)}"><strong>${esc(risk.title)}</strong></label><p class="sub">${esc(risk.fact)}</p><div class="field"><label for="title-${i}">整改标题</label><input id="title-${i}" name="title" value="${esc(risk.title)}" maxlength="100"></div><div class="formgrid"><div class="field"><label for="priority-${i}">优先级</label><select id="priority-${i}" name="priority">${[['LOW','低'],['MEDIUM','中'],['HIGH','高']].map(([value,label])=>`<option value="${value}" ${risk.level===value?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="owner-${i}">负责人</label><select id="owner-${i}" name="owner_id"><option value="">请选择</option>${S.project.members.filter(m=>m.role!=='service_runner').map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></div><div class="field"><label for="due-${i}">截止日期</label><input id="due-${i}" name="due_date" type="date" min="${S.me.today}"></div><div class="field full"><label for="acceptance-${i}">验收标准</label><textarea id="acceptance-${i}" name="acceptance" placeholder="明确可核对的结果和证据要求"></textarea></div></div></section>`).join('')}`,cancelButton+submitButton('核对确认清单'),'prepare-fixes');}
function finalConfirmation(cf){S.confirmation=cf;modal('确认创建整改',`<div class="notice warning">${icon('info')}<span>以下字段将写入整改任务。确认有效至 ${fmt(cf.expires_at)}，参数变化需重新确认。</span></div>${cf.items.map(item=>`<section class="confirmitem"><h3>${esc(item.title)}</h3><p>负责人：${esc(person(item.owner_id))} · 截止：${esc(item.due_date)}</p><p>优先级：${esc({HIGH:'高',MEDIUM:'中',LOW:'低'}[item.priority])}</p><p>问题描述：${esc(item.description)}</p>${item.parent_fix_id?`<p>关联方式：${item.relation==='FOLLOWUP'?'已验收后继续跟进':'拆分事项'} · 来源 ${esc(item.parent_fix_id)}<br>说明：${esc(item.relation_reason)}</p>`:''}<p>验收标准：${esc(item.acceptance)}</p><div class="sub mono">来源 ${esc(item.risk_id)} · 报告 v${cf.report_version}</div></section>`).join('')}<label class="check"><input name="confirmed" type="checkbox" required><span>我已核对清单，明确确认创建以上整改。</span></label>`,cancelButton+submitButton('确认创建整改'),'execute-fixes');}
function fixModal(action){const names={UPDATE:'更新处理记录',SUBMIT:'提交验收',ACCEPT:'通过验收',RETURN:'退回整改',CANCEL:'取消整改',REASSIGN:'改派负责人',RESCHEDULE:'调整截止日'};S.command=action;S.eventKey=key();let fields='';if(action==='REASSIGN')fields=`<div class="field"><label for="new-owner">新负责人</label><select id="new-owner" name="owner_id">${S.project.members.filter(m=>m.role!=='service_runner').map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></div>`;if(action==='RESCHEDULE')fields=`<div class="field"><label for="new-due">新截止日期</label><input id="new-due" type="date" name="due_date" value="${S.detail.data.due_date}" min="${S.me.today}" required></div>`;fields+=`<div class="field"><label for="process-comment">${['SUBMIT','UPDATE'].includes(action)?'处理说明':'验收说明 / 调整原因'}</label><textarea id="process-comment" name="comment" required></textarea></div>`;if(action==='SUBMIT')fields+='<div class="field"><label for="process-evidence">处理证据</label><textarea id="process-evidence" name="evidence" required placeholder="填写检查记录、结果摘要或内部文件定位；证据不会自动视为验收通过"></textarea></div>';modal(names[action],fields,cancelButton+submitButton(names[action]),'fix-transition');}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;try{if(action==='close'){closeModal();return;}button.disabled=true;if(action==='logout'){await api('/auth/logout',{});S.me=null;S.project=null;clearTimeout(poll);location.hash='#/overview';login();return;}if(action==='new'){location.hash='#/new';return;}if(action==='refresh'){S.dirty=false;await refresh();return;}if(action==='open-report'){location.hash='#/reports/'+button.dataset.id;return;}if(action==='ledger-prev'||action==='ledger-next'){S.ledgerPage+=action==='ledger-next'?1:-1;ledgerTable();return;}if(action==='import'){S.import=null;modal('导入任务台账 CSV','<p class="sub">必填字段：task_id、title、status；支持 TODO / IN_PROGRESS / DONE / CANCELLED。整批预检通过后提交，最多 10000 行、4 MB。</p><div class="field"><label for="csv-file">选择 CSV 文件</label><input id="csv-file" type="file" accept=".csv,text/csv"></div><div class="field"><label for="csv-text">或粘贴 CSV 内容</label><textarea id="csv-text" name="csv" class="editbox" required placeholder="task_id,title,owner_id,status,due_date\nT-011,新增任务,u_owner,TODO,2026-11-15"></textarea></div>',cancelButton+submitButton('预检 CSV'),'import-preview');return;}if(action==='commit-import'){await api('/projects/'+S.pid+'/imports/'+S.import.id+'/commit',{});closeModal();toast('台账已整批导入');await refresh();return;}if(action==='download-errors'){const blob=new Blob([JSON.stringify(S.import.errors,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='csv-errors.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return;}if(action==='edit-ledger'){const r=S.project.ledger.find(x=>x.task_id===button.dataset.id);S.editLedger=r;modal('编辑台账任务',`<div class="field"><label>任务编号</label><input value="${esc(r.task_id)}" readonly></div><div class="field"><label for="task-title">任务名称</label><input id="task-title" name="title" value="${esc(r.title)}" required maxlength="200"></div><div class="formgrid"><div class="field"><label for="task-status">状态</label><select id="task-status" name="status">${['TODO','IN_PROGRESS','DONE','CANCELLED'].map(v=>`<option value="${v}" ${r.status===v?'selected':''}>${statusNames[v]}</option>`).join('')}</select></div><div class="field"><label for="task-owner">负责人</label><select id="task-owner" name="owner_id"><option value="">未指定</option>${S.project.members.filter(m=>m.role!=='service_runner').map(m=>`<option value="${m.id}" ${r.owner_id===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><div class="field"><label for="task-due">截止日期</label><input id="task-due" type="date" name="due_date" value="${esc(r.due_date)}"></div><div class="field"><label for="task-done">完成日期</label><input id="task-done" type="date" name="completed_at" value="${esc(r.completed_at?.slice(0,10))}"></div></div>`,cancelButton+submitButton('保存任务'),'edit-ledger');return;}if(action==='withdraw'){reasonModal('撤回审核','withdraw','旧审核单将作废。修改后需提交新的审核单。');return;}if(action==='edit-report'){modal('修订报告正文',`<p class="sub">保留原稿并生成新版本。规则数字与引用保留。人工调整作为独立声明随正文审核，需逐项填写原因。</p><div class="field"><label for="narrative">报告正文</label><textarea id="narrative" class="editbox" name="narrative" required>${esc(S.detail.current.data.narrative)}</textarea></div><details><summary>声明人工指标调整（选填）</summary><p class="sub">每行一个对象，包含 metric、value、reason；保留原规则值，不能把人工调整冒充台账结果。metric 可用 total、completed、completion_rate、period_completed、overdue_count、completed_late。</p><textarea name="adjustments_json" class="mono" rows="5">${esc(JSON.stringify((S.detail.current.data.human_adjustments||[]).map(a=>({metric:a.metric,value:a.value,reason:a.reason})),null,2))}</textarea></details><div class="field"><label for="edit-reason">修改原因</label><input id="edit-reason" name="reason" required></div>`,cancelButton+submitButton('保存新版本'),'edit-report');return;}if(action==='submit-review'){modal('提交审核',`<p class="sub">审核将锁定当前 v${S.detail.current_version} 及其正文 hash。</p><div class="field"><label for="submit-reviewer">审核人</label><select id="submit-reviewer" name="reviewer_id">${reviewers(S.me.user.id)}</select></div>`,cancelButton+submitButton('提交审核'),'submit-review');return;}if(action==='approve'||action==='reject'){S.command=action;S.eventKey=key();modal(action==='approve'?'核对通过并发布':'退回报告修改',`<p class="muted">${action==='approve'?`确认批准正文 v${S.detail.current_version}，并发布给本项目授权成员。此操作不会创建整改。`:'填写具体退回原因，报告修订后需要重新审核。'}</p><div class="pre mono">${esc(S.detail.current.content_hash)}</div><div class="field"><label for="review-comment">审核备注${action==='reject'?'（必填）':'（选填）'}</label><textarea id="review-comment" name="comment" ${action==='reject'?'required':''}></textarea></div>`,cancelButton+submitButton(action==='approve'?'确认通过并发布':'确认退回'),'decision');return;}if(action==='view-version'){const v=S.detail.versions.find(v=>v.version===Number(button.dataset.version));$('#report-content').innerHTML=(v.version!==S.detail.current_version?'<div class="notice warning">正在查看历史版本 v'+v.version+'。请返回当前 v'+S.detail.current_version+' 后再审核。</div>':'')+reportArticle(v.data,v.version,v.reason);document.querySelectorAll('[data-action=approve],[data-action=reject]').forEach(el=>el.disabled=v.version!==S.detail.current_version);document.querySelectorAll('.pilltabs button').forEach(el=>el.classList.toggle('active',el===button));return;}if(action==='evidence'){const ev=S.detail.current.data.evidence.find(e=>e.evidence_id===button.dataset.id);if(ev.kind==='DOCUMENT'){await showKnowledgeEvidence(ev.evidence_id);return;}if(ev.kind==='MILESTONE'){modal('冻结里程碑计划',`<h3>${esc(ev.title)}</h3><p class="sub">计划 v${esc(ev.version)} · 本次运行冻结的计划</p><pre class="pre">${esc(JSON.stringify(ev.milestone,null,2))}</pre>`,'<button type="button" data-action="close">关闭</button>');return;}modal('冻结台账证据',`<h3>${esc(ev.title)}</h3><dl class="keyvalues"><dt>证据编号</dt><dd>${esc(ev.evidence_id)}</dd><dt>定位</dt><dd>${esc(ev.locator)}</dd><dt>快照</dt><dd class="mono">${esc(ev.snapshot_id)}</dd><dt>状态</dt><dd>${tag(ev.row.status)}</dd><dt>负责人</dt><dd>${esc(person(ev.row.owner_id))}</dd><dt>截止日期</dt><dd>${esc(ev.row.due_date||'未提供')}</dd><dt>完成时间</dt><dd>${esc(ev.row.completed_at||'未提供')}</dd><dt>行版本</dt><dd class="mono">${esc(ev.version)}</dd></dl><p class="sub">此记录来自本次冻结快照，不随当前台账更新。</p>`,'<button type="button" data-action="close">关闭</button>');return;}if(action==='prepare-fixes'){prepareFixes();return;}if(action==='cancel-run'){reasonModal('取消运行','cancel-run','取消后不能恢复，等待中的审核单将失效。');return;}if(action==='resume-run'||action==='resume-publish'){const r=action==='resume-run'?S.detail:S.detail.run;await api('/runs/'+r.id+'/resume',{expected_version:r.version});toast('已从原检查点恢复');await refresh();return;}if(action==='fix-transition'){if(button.dataset.command==='START'){await api('/rectifications/'+S.detail.id+'/transition',{action:'START',expected_version:S.detail.version,event_key:key()});toast('已开始处理');await refresh();}else fixModal(button.dataset.command);return;}}catch(error){failure(error,$('#dialog').open?$('#dialog'):document);}finally{if(button.isConnected)button.disabled=false;}});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();const b=Object.fromEntries(new FormData(form));const btn=form.querySelector('button[type=submit]');if(btn)btn.disabled=true;const formType=form.dataset.form;try{if(formType==='login'){await api('/auth/login',b);S.me=null;S.dirty=false;await refresh();return;}if(formType==='new-run'){S.submissionKey??=key();const r=await api('/runs',{...b,include_documents:b.include_documents==='on',project_id:S.pid,acknowledge_gaps:b.acknowledge_gaps==='on',submission_key:S.submissionKey});S.submissionKey=null;S.dirty=false;location.hash='#/runs/'+r.id;toast('汇总已受理，运行状态将自动更新');return;}if(formType==='reason'){if(S.command==='cancel-run')await api('/runs/'+S.detail.id+'/cancel',{expected_version:S.detail.version,reason:b.reason});else await api('/reports/'+S.detail.id+'/withdraw',{expected_version:S.detail.current_version,reason:b.reason});toast(S.command==='withdraw'?'已撤回，旧审核单作废':'运行已取消');}if(formType==='edit-report'){b.adjustments=JSON.parse(b.adjustments_json||'[]');delete b.adjustments_json;await api('/reports/'+S.detail.id+'/edit',{...b,expected_version:S.detail.current_version});toast('已保存为新报告版本');}if(formType==='submit-review'){await api('/reports/'+S.detail.id+'/submit',{...b,expected_version:S.detail.current_version});toast('新审核单已提交');}if(formType==='decision'){const r=S.detail;await api('/approvals/'+r.approval.id+'/decision',{expected_version:r.approval.version,report_version:r.current_version,content_hash:r.current.content_hash,decision:S.command==='approve'?'APPROVE':'REJECT',comment:b.comment,event_key:S.eventKey});toast(S.command==='approve'?'审核已通过，正在发布':'报告已退回待修改');}if(formType==='prepare-fixes'){const r=S.fixReport;const selected=[...form.querySelectorAll('.confirmitem')].filter(el=>el.querySelector('[name=selected]').checked).map(el=>{const risk=r.current.data.risks.find(x=>x.risk_id===el.dataset.risk);const val=name=>el.querySelector(`[name=${name}]`).value;return {risk_id:risk.risk_id,title:val('title'),description:risk.fact,owner_id:val('owner_id'),due_date:val('due_date'),acceptance:val('acceptance'),priority:val('priority')};});const cf=await api('/reports/'+r.id+'/confirmations',{expected_version:r.current_version,items:selected});finalConfirmation(cf);return;}if(formType==='execute-fixes'){const result=await api('/confirmations/'+S.confirmation.id+'/execute',{confirmed:b.confirmed==='on',params_hash:S.confirmation.params_hash});const errors=result.results.filter(x=>x.error);S.lastResults=result;if(errors.length){failure(new Error(errors.map(x=>x.message).join('\n')),form);return;}closeModal();S.dirty=false;toast('整改任务已创建，重复提交将返回原任务');location.hash='#/fixes/'+result.results[0].id;return;}if(formType==='fix-transition'){await api('/rectifications/'+S.detail.id+'/transition',{...b,action:S.command,expected_version:S.detail.version,event_key:S.eventKey});toast('处理状态已保存');}if(formType==='import-preview'){S.import=await api('/projects/'+S.pid+'/imports',{csv:b.csv});const imp=S.import;modal('CSV 预检结果',`<p>共 ${imp.total} 行 · 有效 ${imp.valid} 行 · 错误 ${imp.errors.length} 行</p><p class="sub">新增 ${imp.new} 项，更新 ${imp.updated} 项。有错误时整批不提交。</p>${imp.errors.length?`<div class="error">${imp.errors.slice(0,30).map(e=>`第 ${e.line} 行 / ${esc(e.task_id)}：${esc(e.message)}`).join('<br>')}</div>`:'<div class="notice">'+icon('check')+'全部行通过校验，可以原子提交。</div>'}`,`<button type="button" data-action="close">关闭</button>${imp.errors.length?'<button type="button" data-action="download-errors">下载错误清单</button>':'<button class="primary" type="button" data-action="commit-import">确认整批导入</button>'}`);return;}if(formType==='edit-ledger'){const row={...S.editLedger,...b};const fields=['task_id','title','owner_id','status','planned_start','due_date','completed_at','milestone_id','updated_at'];const csv=fields.join(',')+'\n'+fields.map(f=>'"'+String(row[f]||'').replaceAll('"','""')+'"').join(',');const imp=await api('/projects/'+S.pid+'/imports',{csv});if(imp.errors.length)throw new Error(imp.errors.map(e=>e.message).join('\n'));await api('/projects/'+S.pid+'/imports/'+imp.id+'/commit',{});toast('台账任务已保存，已生成报告的快照不受影响');}closeModal();S.dirty=false;await refresh();}catch(error){failure(error,form);}finally{if(btn?.isConnected)btn.disabled=false;}});
document.addEventListener('input',event=>{if(event.target.id==='ledger-search'){S.ledgerPage=0;ledgerTable();}else if(event.target.closest('[data-form]')&&event.target.closest('[data-form]').dataset.form!=='login')S.dirty=true;});
document.addEventListener('change',async event=>{if(event.target.id==='ledger-status'){S.ledgerPage=0;ledgerTable();}if(event.target.id==='fix-status')$('#fix-table').innerHTML=fixTable(event.target.value);if(event.target.id==='csv-file'){const file=event.target.files[0];if(file){if(file.size>4_000_000){failure(new Error('CSV 不能超过 4 MB'),$('#dialog'));return;}$('#csv-text').value=await file.text();}}});
document.addEventListener('click',event=>{const link=event.target.closest('a[href^="#/"]');if(link&&S.dirty){if(!window.confirm('有尚未提交的内容，确认离开？'))event.preventDefault();else S.dirty=false;}});
window.addEventListener('beforeunload',event=>{if(S.dirty){event.preventDefault();event.returnValue='';}});
window.addEventListener('hashchange',()=>{S.dirty=false;updateNavigation();refresh();});
$('#dialog').addEventListener('cancel',()=>{S.dirty=false;});
window.addEventListener('DOMContentLoaded',refresh);
